import * as THREE from 'three';

// The interactive brush adds a bounded user-authored displacement layer to the
// existing artist-made MPFB head/hair meshes. No face is generated by this code.
// Small strokes are serializable in the character's morphs; per-vertex deltas
// are a runtime cache so a slider move never needs to replay every brush dab.
export const SCULPT_MAX_GESTURES = 40;
export const SCULPT_MAX_SEGMENTS = 64;
const HAIR_CHUNK_VERTICES = 160;

function isValidStroke(s) {
  return Array.isArray(s) && s.length === 8 && s.every(Number.isFinite) &&
    Math.abs(s[0]) < 2 && Math.abs(s[1]) < 2 && Math.abs(s[2]) < 2 &&
    Math.abs(s[3]) <= 0.015 && Math.abs(s[4]) <= 0.015 && Math.abs(s[5]) <= 0.015 &&
    s[6] >= 0.005 && s[6] <= 0.09;
}

function sculptGestures(morphs, tool, style = '') {
  const gestures = morphs?.sculptGestures;
  if (!Array.isArray(gestures)) return [];
  return gestures.slice(-SCULPT_MAX_GESTURES).filter(g =>
    g && g.tool === tool && Array.isArray(g.strokes) &&
    (tool !== 'hair' || g.hairStyle === style));
}

function buildChunkBounds(pos) {
  const chunkCount = Math.ceil(pos.length / (3 * HAIR_CHUNK_VERTICES));
  const bounds = new Float32Array(chunkCount * 6);
  for (let k = 0; k < chunkCount; k++) {
    const b = k * 6;
    bounds[b] = bounds[b + 1] = bounds[b + 2] = Infinity;
    bounds[b + 3] = bounds[b + 4] = bounds[b + 5] = -Infinity;
    const end = Math.min(pos.length, (k + 1) * HAIR_CHUNK_VERTICES * 3);
    for (let i = k * HAIR_CHUNK_VERTICES * 3; i < end; i += 3) {
      for (let a = 0; a < 3; a++) {
        const v = pos[i + a];
        bounds[b + a] = Math.min(bounds[b + a], v);
        bounds[b + a + 3] = Math.max(bounds[b + a + 3], v);
      }
    }
  }
  return bounds;
}

function intersectsChunk(bounds, k, cx, cy, cz, radius) {
  const b = k * 6;
  const dx = Math.max(bounds[b] - cx, 0, cx - bounds[b + 3]);
  const dy = Math.max(bounds[b + 1] - cy, 0, cy - bounds[b + 4]);
  const dz = Math.max(bounds[b + 2] - cz, 0, cz - bounds[b + 5]);
  return dx * dx + dy * dy + dz * dz <= radius * radius;
}

/** Mutate both the visible position buffer and its cached displacement. */
export function applySculptStrokeToBuffer(pos, delta, stroke, hair = false, bounds = null) {
  if (!isValidStroke(stroke) || pos.length !== delta.length) return 0;
  const [cx, cy, cz, dx, dy, dz, r, mirror] = stroke;
  const r2 = r * r;
  let changed = 0;
  const chunks = bounds ? bounds.length / 6 : 1;
  for (let k = 0; k < chunks; k++) {
    // Bounds are captured when the hair brush first touches the mesh. Allow
    // extra travel so a subsequent dab can still reach previously moved tips.
    if (bounds && !intersectsChunk(bounds, k, cx, cy, cz, r + 0.045) &&
      (!mirror || !intersectsChunk(bounds, k, -cx, cy, cz, r + 0.045))) continue;
    const start = bounds ? k * HAIR_CHUNK_VERTICES * 3 : 0;
    const end = bounds ? Math.min(pos.length, start + HAIR_CHUNK_VERTICES * 3) : pos.length;
    for (let i = start; i < end; i += 3) {
      const x = pos[i], y = pos[i + 1], z = pos[i + 2];
      const q = ((x - cx) ** 2 + (y - cy) ** 2 + (z - cz) ** 2) / r2;
      const a = q < 1 ? (1 - q) ** 2 : 0;
      let b = 0;
      if (mirror && Math.abs(cx) > 0.001) {
        const qm = ((x + cx) ** 2 + (y - cy) ** 2 + (z - cz) ** 2) / r2;
        b = qm < 1 ? (1 - qm) ** 2 : 0;
      }
      const weight = Math.max(a, b);
      if (weight < 0.0001) continue;
      // Keep the root of a lock close to its existing scalp placement. In
      // particular, this does NOT move the anatomical cut or the head mesh.
      const rootWeight = hair ? 0.20 + 0.80 * Math.min(1, Math.max(0, (0.112 - y) / 0.10)) : 1;
      const wx = mirror && b > 0 ? (a - b) / (a + b + 1e-6) : 1;
      const sx = dx * weight * wx * rootWeight;
      const sy = dy * weight * rootWeight;
      const sz = dz * weight * rootWeight;
      delta[i] += sx; delta[i + 1] += sy; delta[i + 2] += sz;
      pos[i] += sx; pos[i + 1] += sy; pos[i + 2] += sz;
      changed++;
    }
  }
  return changed;
}

function updateFaceNormals(mesh, active) {
  const geo = mesh.geometry;
  if (!geo?.attributes?.normal) return;
  if (!mesh.userData.originalSculptNormals) {
    // The cached GLB normal attribute is shared with other characters. A
    // brush may ONLY recalculate this particular head's own attribute.
    geo.setAttribute('normal', geo.attributes.normal.clone());
    mesh.userData.originalSculptNormals = Float32Array.from(geo.attributes.normal.array);
  }
  if (active && geo.index) geo.computeVertexNormals();
  else {
    geo.attributes.normal.array.set(mesh.userData.originalSculptNormals);
    geo.attributes.normal.needsUpdate = true;
  }
}

export function applyStoredFaceSculpt(mesh, morphs, basePos) {
  if (!mesh?.geometry?.attributes?.position) return false;
  const pos = mesh.geometry.attributes.position.array;
  const rev = Number(morphs?.sculptRevision) || 0;
  let delta = mesh.userData.sculptDelta;
  if (!delta || delta.length !== pos.length || mesh.userData.sculptRevision !== rev) {
    delta = new Float32Array(pos.length);
    const work = new Float32Array(basePos || pos);
    for (const gesture of sculptGestures(morphs, 'face')) {
      for (const stroke of gesture.strokes.slice(0, SCULPT_MAX_SEGMENTS)) {
        applySculptStrokeToBuffer(work, delta, stroke);
      }
    }
    mesh.userData.sculptDelta = delta;
    mesh.userData.sculptRevision = rev;
    mesh.userData.sculptActive = delta.some(v => Math.abs(v) > 1e-8);
  }
  if (!mesh.userData.sculptActive) {
    if (mesh.userData.originalSculptNormals) updateFaceNormals(mesh, false);
    return false;
  }
  for (let i = 0; i < pos.length; i++) pos[i] += delta[i];
  mesh.geometry.attributes.position.needsUpdate = true;
  mesh.geometry.computeBoundingSphere();
  updateFaceNormals(mesh, true);
  return true;
}

function isBrushableHairMesh(mesh) {
  return mesh.isMesh && mesh.geometry?.attributes?.position &&
    !['ScalpRootFeatherCap', 'ScalpRootStrands', 'BabyHairWisps'].includes(mesh.name);
}

export function getBrushableHairMeshes(rootGroup, includeStrands = true) {
  const hairGroup = rootGroup?.getObjectByName('HairGroup');
  if (!hairGroup) return [];
  const result = [];
  hairGroup.traverse(mesh => {
    if (isBrushableHairMesh(mesh) && (includeStrands || mesh.name !== 'MasterStrandHairMesh')) result.push(mesh);
  });
  return result;
}

function makeUniqueHairGeometry(mesh) {
  const old = mesh.geometry;
  if (old.userData?.sculptUnique) return old;
  // Exactly like the lightweight head clone: never deep-clone morphAttributes
  // or all cached strand buffers, only this instance's position attribute.
  const geo = new THREE.BufferGeometry();
  geo.index = old.index;
  geo.attributes = { ...old.attributes, position: old.attributes.position.clone() };
  geo.morphAttributes = old.morphAttributes;
  geo.morphTargetsRelative = old.morphTargetsRelative;
  geo.groups = old.groups;
  geo.boundingBox = old.boundingBox?.clone() || null;
  geo.boundingSphere = old.boundingSphere?.clone() || null;
  geo.userData = { ...old.userData, sharedBuiltinGeo: false, sculptUnique: true };
  delete geo.userData.sculptDelta;
  delete geo.userData.sculptBounds;
  delete geo.userData.sculptRevision;
  delete geo.userData.sculptOnPositions;
  mesh.geometry = geo;
  return geo;
}

function strokeInMeshSpace(stroke, hairGroup, mesh) {
  const fromGroup = new THREE.Matrix4().copy(mesh.matrixWorld).invert().multiply(hairGroup.matrixWorld);
  const center = new THREE.Vector3(stroke[0], stroke[1], stroke[2]).applyMatrix4(fromGroup);
  const drag = new THREE.Vector3(stroke[3], stroke[4], stroke[5]).transformDirection(fromGroup)
    .multiplyScalar(new THREE.Vector3(stroke[3], stroke[4], stroke[5]).length() * fromGroup.getMaxScaleOnAxis());
  // transformDirection normalizes, so retain distance via the scale above.
  return [center.x, center.y, center.z, drag.x, drag.y, drag.z,
    stroke[6] * fromGroup.getMaxScaleOnAxis(), 0];
}

function addStrokeToHairMesh(mesh, hairGroup, stroke, pos, delta, bounds) {
  let changed = 0;
  const local = strokeInMeshSpace(stroke, hairGroup, mesh);
  changed += applySculptStrokeToBuffer(pos, delta, local, true, bounds);
  if (stroke[7] && Math.abs(stroke[0]) > 0.001) {
    const flipped = [...stroke];
    flipped[0] = -flipped[0];
    flipped[3] = -flipped[3];
    changed += applySculptStrokeToBuffer(pos, delta, strokeInMeshSpace(flipped, hairGroup, mesh), true, bounds);
  }
  return changed;
}

/** Called after the MPFB/head/hair parameters; a cached delta is O(vertices). */
export function applyStoredHairSculpt(rootGroup, morphs = {}) {
  const hairGroup = rootGroup?.getObjectByName('HairGroup');
  if (!hairGroup) return;
  const rev = Number(morphs.sculptRevision) || 0;
  const style = rootGroup.userData.currentHairStyle || '';
  const gestures = sculptGestures(morphs, 'hair', style);
  hairGroup.updateMatrixWorld(true);
  for (const mesh of getBrushableHairMeshes(rootGroup)) {
    let geo = mesh.geometry;
    if (gestures.length && !geo.userData.sculptUnique) geo = makeUniqueHairGeometry(mesh);
    const pos = geo.attributes.position.array;
    let oldDelta = geo.userData.sculptDelta;
    if (!oldDelta && !gestures.length) continue;
    if (geo.userData.sculptRevision !== rev || geo.userData.sculptStyle !== style || oldDelta?.length !== pos.length) {
      if (geo.userData.sculptOnPositions && oldDelta?.length === pos.length) {
        for (let i = 0; i < pos.length; i++) pos[i] -= oldDelta[i];
      }
      const delta = new Float32Array(pos.length);
      if (gestures.length) {
        const bounds = buildChunkBounds(pos);
        for (const gesture of gestures) {
          for (const stroke of gesture.strokes.slice(0, SCULPT_MAX_SEGMENTS)) {
            if (isValidStroke(stroke)) addStrokeToHairMesh(mesh, hairGroup, stroke, pos, delta, bounds);
          }
        }
      }
      geo.userData.sculptDelta = delta;
      geo.userData.sculptBounds = null;
      geo.userData.sculptRevision = rev;
      geo.userData.sculptStyle = style;
      geo.userData.sculptOnPositions = true;
      geo.attributes.position.needsUpdate = true;
    } else if (!geo.userData.sculptOnPositions && oldDelta) {
      for (let i = 0; i < pos.length; i++) pos[i] += oldDelta[i];
      geo.userData.sculptOnPositions = true;
      geo.attributes.position.needsUpdate = true;
    }
  }
}

/** Immediate update while dragging; the gesture's revision was set on down. */
export function applyLiveSculptStroke(rootGroup, tool, stroke) {
  if (!isValidStroke(stroke) || !rootGroup) return 0;
  let changed = 0;
  if (tool === 'face') {
    const mesh = rootGroup.getObjectByName('HeadSkinMesh');
    const attr = mesh?.geometry?.attributes?.position;
    if (!attr) return 0;
    const delta = mesh.userData.sculptDelta ||= new Float32Array(attr.array.length);
    changed = applySculptStrokeToBuffer(attr.array, delta, stroke);
    if (changed) {
      attr.needsUpdate = true;
      mesh.userData.sculptActive = true;
    }
  } else if (tool === 'hair') {
    const group = rootGroup.getObjectByName('HairGroup');
    if (!group) return 0;
    group.updateMatrixWorld(true);
    for (const mesh of getBrushableHairMeshes(rootGroup)) {
      const geo = makeUniqueHairGeometry(mesh);
      const attr = geo.attributes.position;
      const delta = geo.userData.sculptDelta ||= new Float32Array(attr.array.length);
      const bounds = geo.userData.sculptBounds ||= buildChunkBounds(attr.array);
      const n = addStrokeToHairMesh(mesh, group, stroke, attr.array, delta, bounds);
      if (n) { attr.needsUpdate = true; changed += n; }
    }
  }
  return changed;
}

export function finalizeSculptStroke(rootGroup, tool) {
  if (tool === 'face') {
    const mesh = rootGroup?.getObjectByName('HeadSkinMesh');
    if (mesh?.geometry) {
      mesh.geometry.computeBoundingBox();
      mesh.geometry.computeBoundingSphere();
      // Skin is indexed; unlike alpha-cut hair cards it can safely be
      // smoothed once per finished gesture rather than on every pointer move.
      updateFaceNormals(mesh, Boolean(mesh.userData.sculptActive));
    }
    return;
  }
  for (const mesh of getBrushableHairMeshes(rootGroup)) {
    if (!mesh.geometry?.userData.sculptUnique) continue;
    mesh.geometry.computeBoundingBox();
    mesh.geometry.computeBoundingSphere();
  }
}
